from robot.api import logger
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.generic_commands.commands_default_params import COMMAND_PARAMS_DEFAULT_VALUE
from ta_egate_cmd_parser.generic_commands.commands_params_order import COMMAND_PARAMS_ORDER


class GenericCommandFailure(Exception):
    """
    Exception class for generic command without output.
    """
    pass


class GenericCommand(EgateCommandBase):
    """

    """

    def __init__(self, cmd, executed_phrase=r'.*?EGATE>', raw_cmd_params=None, **params):
        """

        :param cmd: Egate command name
        :param executed_phrase: phrase to catch after executing command
        :param raw_cmd_params: string with command params
        :param params: dict with command params
        """
        super(GenericCommand, self).__init__()
        self.executed_phrase = executed_phrase
        self.command = cmd
        self.raw_cmd_params = raw_cmd_params
        self.params = params
        self.fail_regexp = 'ERR:|Error:'
        self.to_execute = self.command
        self._build_command()

        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute(self, egate_id=0):
        """
        Execute command.

        :return: command status and output
        """
        status, output = super(GenericCommand, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            return status, output
        else:
            raise GenericCommandFailure(output)

    def _build_command(self):
        """
        Build command.

        :return: None
        """
        if self.raw_cmd_params:
            self._build_command_from_raw_params()
        elif self.command in list(COMMAND_PARAMS_ORDER.keys()):
            self._build_command_with_ordered_params()
        else:
            self._build_command_from_params()

    def _build_command_from_params(self):
        for param, value in list(self.params.items()):
            if param in ['reset', 'clear', 'flush', 'allow_mobility', 'disp', 'add', 'del', 'replace', 'clean']:
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)
        if self.command in list(COMMAND_PARAMS_DEFAULT_VALUE.keys()):
            self._add_command_default_params()

    def _build_command_with_ordered_params(self):
        for param in COMMAND_PARAMS_ORDER[self.command]:
            if param in self.params and param in ['reset', 'clear', 'flush', 'allow_mobility', 'disp', 'add', 'del', 'replace', 'clean']:
                self.to_execute += ' {}'.format(param)
            elif param in self.params:
                self.to_execute += ' {}={}'.format(param, self.params[param])

    def _build_command_from_raw_params(self):
        self.to_execute += ' {}'.format(self.raw_cmd_params)

    def _add_command_default_params(self):
        for default_param, param_value in COMMAND_PARAMS_DEFAULT_VALUE[self.command].items():
            if default_param not in list(self.params.keys()):
                self.to_execute += ' {}={}'.format(default_param, param_value)
